(function(root){
const t=s=>typeof I18n!=='undefined'?I18n.text(s):s,ui=(parts,...values)=>parts.reduce((out,p,i)=>out+t(p)+(i<values.length?String(values[i]??''):''),'');
const BASE='https://api.themoviedb.org/3/';
async function request(path,credential,params={},fetcher=fetch){
 const key=String(credential||'').trim().replace(/^Bearer\s+/i,'');if(!key)throw Error(t("请先填写 TMDb API Key 或 Read Access Token"));
 const url=new URL(path,BASE);if(url.origin!=='https://api.themoviedb.org'||!url.pathname.startsWith('/3/'))throw Error(t("无效的 TMDb 请求"));
 url.searchParams.set('language',typeof I18n!=='undefined'?I18n.getLanguage():'zh-CN');Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,String(v)));
 const headers={Accept:'application/json'};if(/^[a-f0-9]{32}$/i.test(key))url.searchParams.set('api_key',key);else headers.Authorization='Bearer '+key;
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
 try{const response=await fetcher(url.toString(),{headers,signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok){const error=Error(response.status===401?t("凭证无效，请检查 TMDb API Key / Token"):response.status===429?t("请求太频繁，请稍后重试"):ui`TMDb 请求失败（${response.status}）`);error.status=response.status;throw error;}return await response.json()}catch(error){if(error.name==='AbortError')throw Error(t("连接超时，请检查网络后重试"));if(error instanceof TypeError)throw Error(t("无法连接 TMDb，请检查网络或浏览器跨域限制"));throw error}finally{clearTimeout(timer)}
}
function imageUrl(path,size='w500'){return typeof path==='string'&&/^\/[A-Za-z0-9_.-]+$/.test(path)?'https://image.tmdb.org/t/p/'+size+path:''}
function metadata(data,type){const credits=data.aggregate_credits||data.credits||{},people=(list,crew=false)=>{const unique=new Map();for(const p of list||[]){if(!p?.name)continue;const roles=crew?(p.jobs?.map(j=>j.job)||[p.job]):(p.roles?.map(r=>r.character)||[p.character]);const role=[...new Set(roles.filter(Boolean))].join(' / ');if(unique.has(p.id)){const old=unique.get(p.id);old.role=[...new Set([...old.role.split(' / '),...roles.filter(Boolean)])].join(' / ')}else unique.set(p.id,{id:p.id,name:p.name,role,image:imageUrl(p.profile_path,'w185')})}return [...unique.values()]};
 const logos=[...(data.images?.logos||[])].sort((a,b)=>{const rank=l=>(typeof I18n!=='undefined'&&I18n.getLanguage()==='en-US'?{en:0,zh:1,ja:2}:{zh:0,ja:1,en:2})[l]??3;return rank(a.iso_639_1)-rank(b.iso_639_1)||(b.vote_average||0)-(a.vote_average||0)});const runtime=type==='movie'?data.runtime:(data.episode_run_time?.find(t=>t>0)||data.last_episode_to_air?.runtime||null);
 return{metadataLanguage:typeof I18n!=='undefined'?I18n.getLanguage():'zh-CN',detailsVersion:2,endDate:type==='movie'?(data.status==='Released'?data.release_date||'':''):(['Ended','Canceled'].includes(data.status)?data.last_air_date||'':''),airDate:data.first_air_date||data.release_date||'',broadcastStatus:data.status||'',seasonCount:type==='movie'?null:(data.number_of_seasons??null),runtime:Number(runtime)>0?Number(runtime):null,homepage:typeof data.homepage==='string'&&/^https?:\/\//i.test(data.homepage)?data.homepage:'',heroImage:imageUrl(data.poster_path,'w780')||imageUrl(data.backdrop_path,'w1280'),titleLogo:imageUrl(logos[0]?.file_path),overview:String(data.overview||''),tmdbRating:Number(data.vote_average)||0,tmdbVoteCount:Number(data.vote_count)||0,genre:data.genres?.map(g=>g.name).join(' · ')||t("动画"),cast:people(credits.cast),crew:people([...(data.created_by||[]).map(p=>({...p,job:'Creator'})),...(credits.crew||[])],true),seasons:(data.seasons||[]).map(s=>({number:s.season_number,name:s.name||t("第 ")+s.season_number+t(" 季"),episodes:s.episode_count||0,airDate:s.air_date||'',image:imageUrl(s.poster_path,'w500')}))}
}
function normalize(data,type){const count=type==='movie'?1:Number(data.number_of_episodes);return{id:Date.now()+Math.floor(Math.random()*1000),tmdbId:data.id,tmdbType:type,title:String(data.name||data.title||data.original_name||data.original_title||t("未命名")).slice(0,100),en:data.original_name||data.original_title||'',year:Number((data.first_air_date||data.release_date||'').slice(0,4))||new Date().getFullYear(),episodes:Number.isInteger(count)&&count>0?Math.min(count,9999):1,episodeCountUnknown:type==='tv'&&!(count>0),progress:0,status:'planned',rating:0,tag:'',image:imageUrl(data.poster_path,'w342'),favorite:false,...metadata(data,type)}}
function animationResults(data,type){return(data.results||[]).filter(a=>!a.adult&&a.genre_ids?.includes(16)).map(a=>({...a,media_type:type}))}
const api={request,normalize,animationResults,metadata,imageUrl};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.TMDB=api;
})(globalThis);
